bool wordBreak(String word, List<String> dictionary) {
  Set<String> dict = dictionary.toSet();
  List<bool> dp = List.filled(word.length + 1, false);
  dp[0] = true; 
  for (int i = 1; i <= word.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && dict.contains(word.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  return dp[word.length];
}

int minWordBreak(String word, List<String> dictionary) {
  Set<String> dict = dictionary.toSet();
  int n = word.length;
  List<int> dp = List.filled(n + 1, 1 << 30);
  dp[0] = 0; 
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dict.contains(word.substring(j, i)) && dp[j] != 1 << 30) {
        int cost = dp[j] + 1;
        if (cost < dp[i]) {
          dp[i] = cost;
        }
      }
    }
  }
  return dp[n] == 1 << 30 ? -1 : dp[n];
}

List<List<String>> wordBreakII(String word, List<String> dictionary) {
  Set<String> dict = dictionary.toSet();
  int n = word.length;
  List<List<String>> result = [];
  List<bool> dp = List.filled(n + 1, false);
  dp[0] = true; 
  for (int i = 1; i <= n; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && dict.contains(word.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }
  if (!dp[n]) return result;
  List<List<String>> segments = [];
  List<String> prefix = [];
  void backtrack(int index) {
    if (index == n) {
      if (prefix.isNotEmpty) segments.add(List.from(prefix));
      return;
    }
    for (int i = index; i < n; i++) {
      if (dp[i] && dict.contains(word.substring(index, i + 1))) {
        prefix.add(word.substring(index, i + 1));
        backtrack(i + 1);
        prefix.removeLast();
      }
    }
  }
  backtrack(0);
  return segments;
}

