      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break;
      }
    }
  }

  return dp[s.length];
}

int minWordBreak(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<int> dp = List.filled(s.length + 1, 0);

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (wordSet.contains(s.substring(j, i))) {
        if (dp[j] != 0) {
          dp[i] = dp[j] + 1;
        }
      }
    }
  }

  return dp[s.length];
}

List<List<String>> wordBreakAll(String s, List<String> wordDict) {
  Set<String> wordSet = wordDict.toSet();
  List<List<String>> results = [];

  void backtrack(int start, String currentWord, List<String> seg) {
    if (start == s.length) {
      results.add(List.from(seg)); 
      return;
    }

    for (int i = start; i < s.length; i++) {
      String word = s.substring(start, i + 1);
      if (wordSet.contains(word)) {
        seg.add(word);
        backtrack(i + 1, word, seg);
        seg.removeLast(); 
      }
    }
  }

  backtrack(0, '', []);
  return results;
}

