void fn0() {


  List<List<int>> wordBreak(String s, List<String> wordDict) {
    int n = s.length;
    Set<String> wordSet = wordDict.toSet();
    List<List<int>> dp = List.generate(n + 1, (_) => List.filled(n + 1, 0));

    for (int i = 1; i <= n; i++) {
      for (int j = 0; j < i; j++) {
        bool wordFound = false;
        if (wordSet.contains(s.substring(j, i))) {
          wordFound = true;
        }

        if (!wordFound) {
          dp[i][j] = dp[i - 1][j];
        } else {
          dp[i][j] = dp[i - 1][j] < dp[i][j - 1]
              ? dp[i - 1][j]
              : dp[i][j - 1] + 1;
        }
      }
    }

    List<List<int>> result = List.generate(n + 1, (_) => List.filled(n + 1, 0));
    int k = n;
    int p = n;

    while (k >= 1) {
      while (p >= 1 && dp[k][p] == dp[k - 1][p]) {
        result[k][p - 1] = s.substring(p, p + 1);
        p--;
      }
      k--;
      p = k;
    }

    return result;
  }

  String s1 = "leetcode";
  List<String> wordDict1 = ["leet", "code"];
  List<List<int>> wordBreak1 = wordBreak(s1, wordDict1);

