Map<String, int> fn0(List<String> commands) {
  final int n = commands.length;
  final List<String> stack = <String>[];
  final List<List<String>> history = <List<String>>[];
  int duration = 0;
  bool broken = false;

  void undo() {
    if (stack.isEmpty) {
      broken = true;
      return;
    }
    final String last = stack.removeLast();
    if (last == 'BEGIN') {
      history.removeLast();
    } else if (last == 'END') {
      history.add(List.from(stack));
    } else if (last == 'ADD') {
      stack.add(history.removeLast()[stack.length - 1]);
    } else if (last == 'UNDO') {
      final List<String> saved = List.from(stack);
      stack.add(saved.removeLast());
    }
  }

  for (int i = 0; i < n; i++) {
    final String cmd = commands[i];
    if (cmd == 'BEGIN') {
      stack.add(cmd);
      history.add([]);
    } else if (cmd == 'END') {
      if (stack.isEmpty) {
        broken = true;
        continue;
      }
      if (stack.removeLast() != 'BEGIN') {
        broken = true;
        continue;
      }
      final List<String> saved = List.from(stack);
      stack.removeLast();
      history.removeLast();
      for (int j = saved.length - 1; j >= 0; j--) {
        stack.add(saved[j]);
      }
    } else if (cmd == 'ADD') {
      if (stack.isEmpty) {
        broken = true;
        continue;
      }
      final String prev = stack.removeLast();
      if (prev != 'BEGIN' && prev != 'END') {
        broken = true;
        continue;
      }
      final List<String> saved = List.from(stack);
      stack.add('$prev/ADD');
      history.add(List.from(saved));
    } else if (cmd == 'UNDO') {
      if (stack.isEmpty) {
        continue;
      }
      final List<String> saved = List.from(stack);
      undo();
      stack.add('$prev/UNDO');
      history.add(List.from(saved));
    } else {
      final int? parseInt = int.tryParse(cmd);
      if (parseInt != null) {
        duration += parseInt;
        if (duration > 0) {
          stack.add('$duration/ADD');
        }
      } else {
        broken = true;
      }
    }
  }

  if (stack.isNotEmpty) {
    broken = true;
  }

  if (broken) {
    final List<String> saved = List.from(stack);
    stack.clear();
    history.clear();
  }

  return {
    'duration': duration,
    'broken': broken ? 1 : 0
  };
}

