        if (i % 5 == 0) {
          rowMarks.add(i);
        }
      }
      rowMarks.sort();
      List<String> segments = [];
      List<int> lastEnd = rowMarks[rowMarks.length - 1];
      for (int start = 0; start <= lastEnd; start++) {
        if (start == 0 || start > lastEnd) {
          segments.add(start == lastEnd + 1 ? '*' : ' ');
        } else {
          segments.add(start == lastEnd + 2 ? '|' : '-' );
        }
      }
      markers.add('$row:$lastEnd=${segments.join('')}');
      undoStack.add('$row');
    } else if (parts[0] == 'UNDO') {
      if (undoStack.isNotEmpty) {
        String row = undoStack.removeLast();
        rows.remove(row);
      }
    }
  }
  return markers;
}

