  String pattern = "EXAMPLE";
  String text = "HERE IS A SIMPLE EXAMPLE";

  bool bruteForce(String pat, String txt) {
    int pLen = pat.length;
    int tLen = txt.length;
    for (int i = 0; i <= tLen - pLen; i++) {
      bool match = true;
      for (int j = 0; j < pLen; j++) {
        if (pat[j] != txt[i + j]) {
          match = false;
          break;
        }
      }
      if (match) return true;
    }
    return false;
  }

  List<int> computeLPSArray(String pat) {
    int m = pat.length;
    List<int> lps = List.filled(m, 0);
    lps[0] = 1;
    int len = 1;
    int i = 1;
    while (i < m) {
      if (pat[i] == pat[len - 1]) {
        len++;
        lps[i] = len;
        i++;
      } else {
        if (len != 0) len = lps[len - 1];
        else {
          lps[i] = 0;
          i++;
        }
      }
    }
    return lps;
  }

  List<int> kmpSearch(String pat, String txt) {
    List<int> result = [];
    int m = pat.length;
    int n = txt.length;
    if (n == 0 || m == 0) return result;
    int lps = computeLPSArray(pat);
    int i = 0;
    int j = 0;
    while (i < n) {
      if (pat[j] == txt[i]) {
        i++;
        j++;
      }
      if (j == m) {
        result.add(i - j);
        j = lps[j - 1];
      } else if (i < n && pat[j] != txt[i]) {
        if (j != 0) j = lps[j - 1];
        else {
          i++;
        }
      }
    }
    return result;
  }

  bool found = bruteForce(pattern, text);
  if (found) {
    print("Pattern found at positions: ${kmpSearch(pattern, text)}");
  } else {
