    if (req[0] > maxX) maxX = req[0];
    if (req[1] < minY) minY = req[1];
    if (req[1] > maxY) maxY = req[1];
  }
  int totalArea = (maxX - minX) * (maxY - minY);
  int covered = 0;

  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      int root1 = find(requests[i][0]);
      int root2 = find(requests[j][0]);
      if (root1 == root2) continue;
      int root1y = find(requests[i][1]);
      int root2y = find(requests[j][1]);
      if (root1y == root2y) continue;
      int root1x = find(requests[i][0]);
      int root2x = find(requests[j][0]);
      int root1y1 = find(requests[i][1]);
      int root2y1 = find(requests[j][1]);
      if ((root1x <= minX && root2x >= maxX) || (root2x <= minX && root1x >= maxX)) {
        if ((root1y1 <= minY && root2y1 >= maxY) || (root2y1 <= minY && root1y1 >= maxY)) {
          covered += (maxX - minX) * (maxY - minY);
          continue;
        }
      }
      if ((root1x <= minX && root2x >= maxX) && (root1y1 <= minY && root2y1 >= maxY) ||
