String fn0(String pixels) {
  if (pixels.isEmpty) return '';
  final Set<String> visited = <String>{};
  final Set<int> visitedDominant = <int>{};
  final List<int> xs = <int>[];
  final List<int> ys = <int>[];
  final List<String> names = <String>[];
  final List<int> xsDominant = <int>[];
  final List<int> ysDominant = <int>[];

  for (final String token in pixels.split(',')) {
    final String trimmed = token.trim();
    if (trimmed.isEmpty) continue;
    final List<String> parts = trimmed.split(':');
    if (parts.length != 3) continue;

    final String? name = parts[0].trim();
    if (name == null || name.isEmpty) continue;
    final String? value = parts[1].trim();
    if (value == null || value.isEmpty) continue;
    final String? group = parts[2].trim();
    if (group == null || group.isEmpty) continue;

    bool validName = false;
    bool validValue = false;
    bool validGroup = false;

    if (name.length <= 8) {
      validName = true;
      for (int i = 0; i < name.length; i++) {
        if (name.codeUnitAt(i) < 97 || name.codeUnitAt(i) > 122) {
          validName = false;
          break;
        }
      }
    }
    if (value.length <= 3) {
      validValue = true;
      for (int i = 0; i < value.length; i++) {
        final String ch = value[i];
        if (ch.codeUnitAt(0) < 49 || ch.codeUnitAt(0) > 57) {
          validValue = false;
          break;
        }
      }
    }
    if (group == 'B' || group == 'G' || group == 'R') {
      validGroup = true;
    }

    if (validName && validValue && validGroup) {
      final int x = int.parse(value);
      final int y = int.parse(name);
      visited.add('${name}:${value}:${group}');
      if (group == 'R' || group == 'G' || group == 'B') {
        visitedDominant.add(x);
      }
      xs.add(x);
      ys.add(y);
      names.add(name);
    }
  }

  if (xs.isEmpty) return '';

  xs = xs.toList()..sort();
  ys = ys.toList()..sort();

  for (int i = 0; i < xs.length - 1; i++) {
    for (int j = 0; j < ys.length - 1; j++) {
      bool surrounded = true;
      for (int k = i; k <= i + 1; k++) {
        for (int l = j; l <= j + 1; l++) {
          final String key = '${names[k]},${names[l]}';
          if (visited.contains(key)) {
            surrounded = false;
            break;
          }
        }
        if (!surrounded) break;
      }
      if (surrounded) {
        xsDominant.add(xs[i]);
        ysDominant.add(ys[j]);
      }
    }
  }

  if (xsDominant.isEmpty) return '';

  return (xsDominant.toSet().toList()..sort()).join(',');
}

