int totalCombinations(int k, int n, List<String> items) {
  int total = 0;
  for (var i = 0; i < (1 << n); i++) {
    final int count = (i & (1 << k)) != 0 ? 1 : 0;
    total += count;
  }
  return total;
}

List<String> combination(int i, int k, int n, List<String> items) {
  final List<String> result = [];
  for (var j = 0; j < n; j++) {
    if (((i >> j) & 1) == 1) {
      result.add(items[j]);
    }
  }
  return result;
}

