      for (int m = 0; m < numDays * numHours; m++) {
        if (userActivity[m] == 0) {
          low++;
        } else if (userActivity[m] == 1) {
          medium++;
        } else {
          high++;
        }
      }

      activity[i] = [low, medium, high];
