        row += '  ';
      } else {
        int label = totalLow >= numUsers * numHours
            ? legend[2]
            : totalLow >= numUsers * numHours ~/ 2
                ? legend[1]
                : legend[0];

        if (activity[minute ~/ numHours][minute % numHours] == 0) {
          row += label;
        } else if (activity[minute ~/ numHours][minute % numHours] == 1) {
          row += '*';
        } else {
          row += '#';
        }
      }
