List<String> fn0(List<String> logs, List<String> apps) {
  List<String> results = [];
  if (apps.isEmpty) {
    return results;
  }
  Map<String, String> appToBin = {};
  for (String app in apps) {
    appToBin[app] = app.length < 5 ? 'DEBUG' : 'INFO';
  }
  if (appToBin.isEmpty) {
    return results;
  }
  List<String> stack = [];
  List<String> pending = [];
  Set<String> visited = {};
  List<String> undoStack = [];
  Set<String> pendingSet = {};
  List<double> pendingScores = [];
  List<String> pendingApps = [];
  for (String entry in logs) {
    String trimmed = entry.trim();
    if (trimmed.isEmpty) {
      continue;
    }
    int spaceIndex = trimmed.indexOf(' ');
    if (spaceIndex == -1) {
      continue;
    }
    String level = trimmed.substring(0, spaceIndex);
    String message = trimmed.substring(spaceIndex + 1);
    String app = message.isEmpty ? '' : message[0];
    String bin = appToBin[app] ?? 'DEBUG';
    if (level != bin) {
      continue;
    }
    String? severity;
    if (message.contains(':')) {
      int colonIndex = message.indexOf(':');
      if (colonIndex != -1) {
        severity = message.substring(0, colonIndex);
        message = message.substring(colonIndex + 1);
      }
    }
    if (severity == 'DEBUG' || severity == 'INFO') {
      stack.add(app);
      pending.clear();
      pendingSet.clear();
      pendingScores.clear();
      pendingApps.clear();
      visited.clear();
      undoStack.clear();
      continue;
    }
    if (message.isNotEmpty && severity == 'WARN') {
      String verb = message[0];
      if (verb.isUpper()) {
        pending.add(verb);
        pendingSet.add(verb);
        pendingScores.add(0.0);
        pendingApps.add(app);
      }
    } else if (message.isNotEmpty && severity == 'ERROR') {
      List<String> tokens = message.split(' ');
      if (tokens.length >= 2) {
        String lastToken = tokens[tokens.length - 1];
        if (lastToken.length < 5) {
          pending.add(lastToken);
          pendingSet.add(lastToken);
          pendingScores.add(0.0);
          pendingApps.add(app);
        }
      }
    }
    bool processed = false;
    for (String token in pending) {
      if (token.length >= 5) {
        processed = true;
        break;
      }
    }
    if (!processed) {
      results.add(message);
    }
  }
  while (pending.isNotEmpty) {
    String next = pending[0];
    pending.removeAt(0);
    pendingSet.remove(next);
    pendingScores.removeAt(0);
    pendingApps.removeAt(0);
    bool valid = true;
    for (String token in pending) {
      if (token.isNotEmpty && token.length < 5) {
        valid = false;
        break;
      }
    }
    if (!valid) {
      results.add(next);
    } else {
      double score = pendingScores[0];
      String app = pendingApps[0];
      double best = score;
      String bestApp = app;
      for (String token in pending) {
        double s = 0.0;
        bool valid = true;
        for (String app in apps) {
          if (token == app) {
            s = 1.0;
            break;
          }
        }
        if (s > best) {
          best = s;
          bestApp = token;
        }
      }
      results.add('$bestApp:$best');
      if (best == 1.0) {
        for (String token in pending) {
          if (token.isNotEmpty) {
            undoStack.add(token);
          }
        }
      }
    }
  }
  results.sort();
  return results;
}

