    while (x >= 0 && x < rows.length && y >= 0 && y < rows.length) {
      final int code = rows.codeUnitAt(x);
      final bool isLetter = code >= 97 && code <= 122;
      final bool isSpace = code == 32;

      if (isLetter) {
        tokens.add('$x,$y');
        xs.add(x);
        ys.add(y);
      } else if (isSpace) {
        break;
      } else {
        break;
      }

      x++;
      y++;
    }

    if (tokens.isEmpty) continue;

    if (x >= 0 && x < rows.length && y >= 0 && y < rows.length) {
      final bool isLetter = rows.codeUnitAt(x) >= 97 && rows.codeUnitAt(x) <= 122;
      if (!isLetter) continue;
    }

    if (tokens.length < width) {
      tokens.add('$x,$y');
      xs.add(x);
      ys.add(y);
