List<String> fn0(List<String> cells) {
  if (cells.isEmpty) return [];

  Set<String> visited = {};
  Set<int> repeatedIds = {};
  Set<List<int>> repeatedCoords = {};

  for (String cell in cells) {
    if (cell.isEmpty) continue;

    List<String> parts = cell.split('|');
    if (parts.length != 2) continue;

    visited.add(parts[0]);
    repeatedIds.add(int.parse(parts[1]));

    List<String> walls = parts[0].split(',');
    List<int> coordinates = [
      int.parse(walls[0]),
      int.parse(walls[1]),
      int.parse(walls[2]),
      int.parse(walls[3])
    ];

    List<int> neighbors = [
      (coordinates[0] - 1) * 4 + (coordinates[1] - 1),
      (coordinates[0] - 1) * 4 + coordinates[2],
      coordinates[0] * 4 + (coordinates[1] - 1),
      coordinates[0] * 4 + coordinates[3]
    ];

    for (int id in neighbors) {
      if (visited.contains(id.toString())) continue;

      visited.add(id.toString());
      repeatedIds.add(id);

      List<int> neighborCoords = [
        walls[0], walls[1], walls[2], walls[3]
      ];

      for (int i = 0; i < 4; i++) {
        int ni = neighbors[i];
        int nc = neighborCoords[i];

        if (ni < 0 || ni >= 4) continue;

        if (repeatedCoords.contains([nc, ni])) {
          repeatedCoords.removeWhere((e) => e[1] == ni);
        } else {
          repeatedCoords.add([nc, ni]);
        }
      }
    }
  }

  List<String> result = [];
  for (String cell in cells) {
    if (cell.isEmpty) continue;

    List<String> parts = cell.split('|');
    int id = int.parse(parts[1]);

    if (repeatedIds.contains(id)) {
      result.add(cell);
    }
  }

  result.sort((a, b) {
    List<String> pa = a.split('|');
    List<String> pb = b.split('|');

    int sa = int.parse(pa[1]);
    int sb = int.parse(pb[1]);

    if (sa != sb) return sa.compareTo(sb);

    double da = double.parse(pa[0].split(',').first);
    double db = double.parse(pb[0].split(',').first);

    if (da != db) return da.compareTo(db);

    String oa = pa[0].split(',').last;
    String ob = pb[0].split(',').last;

    return oa.compareTo(ob);
  });

  return result;
}

