Map<String, int> fn0(List<int> arrivalTimes) {
  if (arrivalTimes.isEmpty) return {"pairCount": 0, "mashupDuration": 0};
  int n = arrivalTimes.length;
  if (n < 2) return {"pairCount": 0, "mashupDuration": 0};

  int pairCount = 0;
  int maxMashupDuration = 0;

  void search(int left, int right) {
    if (left > right) return;

    if (right - left + 1 >= 4) {
      int maxDuration = 0;
      bool allWithinLimit = true;

      for (int i = left; i <= right; i++) {
        int k = arrivalTimes[i];
        if (k < 0) {
          allWithinLimit = false;
          break;
        }
        int j = i + 1;
        while (j <= right && arrivalTimes[j] < k) {
          j++;
        }
        if (j > i + 2) {
          int duration = j - i;
          if (duration > maxDuration) {
            maxDuration = duration;
          }
        }
      }

      if (allWithinLimit && maxDuration > maxMashupDuration) {
        pairCount++;
        maxMashupDuration = maxDuration;
      }
    }

    search(left + 1, right);

    for (int i = left + 1; i < right; i++) {
      search(left, i - 1);
      search(i + 1, right);
    }
  }

  search(0, n - 1);
  return {"pairCount": pairCount, "mashupDuration": maxMashupDuration};
}

