  Quaternion(this.x, this.y, this.z, this.w);

  @override
  String toString() => 'Quaternion($x, $y, $z, $w)';

  @override
  bool operator ==(Object other) =>
      other is Quaternion && x == other.x && y == other.y && z == other.z && w == other.w;

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ z.hashCode ^ w.hashCode;

  Quaternion operator +(Object other) {
    if (other is Quaternion) {
      return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
    }
    throw ArgumentError('Unsupported operand type');
  }

  Quaternion operator -(Object other) {
    if (other is Quaternion) {
      return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
    }
    throw ArgumentError('Unsupported operand type');
  }

  Quaternion operator * (Object other) {
    if (other is Quaternion) {
      double xx = x * x, yy = y * y, zz = z * z;
      return Quaternion(
          xx * other.w + other.x * z * 2,
          yy * other.w + other.y * z * 2,
          zz * other.w + other.z * x * 2,
          w * other.w - xx - yy - zz);
    }
    throw ArgumentError('Unsupported operand type');
  }

  Quaternion conjugate() => Quaternion(x, y, z, -w);

  double norm() {
    double sum = x * x + y * y + z * z + w * w;
    if (sum == 0) {
      return 0.0;
    }
    return sqrt(sum);
  }

  Quaternion inverse() => this * conjugate();

  Quaternion normalized() {
    double norm = norm();
    if (norm == 0) {
      return 0.0;
    }
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

