    double sinA = sin(angle);
    double cosA = cos(angle);
    double xx = x * x, yy = y * y, zz = z * z;
    return Quaternion(
        (xx + yy - zz) * cosA + 2 * z * w * sinA,
        (xx - yy - zz) * sinA + 2 * x * w * cosA,
        (zz - xx - yy) * sinA + 2 * y * w * cosA,
        w * (x * z * 2 + y * w * 2));
  }
}

