    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  Quaternion invert() => conjugate() * normalize();

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

