class Quaternion {
  final double x, y, z, w;
  static const double EPSILON = 1.0e-6;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion.unit() : this(1.0, 1.0, 1.0, 1.0);

  const Quaternion.fromList(List<double> list)
      : this(list[0], list[1], list[2], list[3]);

  const Quaternion.fromAxisAngle(double ax, double ay, double az, double theta) {
    double sx = ax * ax, sy = ay * ay, sz = az * az;
    double sc = sx + sy + sz;
    double cosHalf = sc / 2.0;
    double sinHalf = sc * EPSILON;
    double x = ax * cosHalf - az * sinHalf;
    double y = ay * cosHalf + az * sinHalf;
    double z = az * cosHalf - ax * sinHalf;
    double w = sx * sy - sz * sc;
    return Quaternion(x, y, z, w);
  }

  const Quaternion.fromComplex(double re, double im) {
    return Quaternion(re * 0.5, im * 0.5, -im * 0.5, re * 0.5);
  }

  const Quaternion.fromAxisAngleComplex(double ax, double ay, double az, double theta) {
    double re = ax * ax + ay * ay + az * az;
    double im = 2 * (ax * ay * az);
    return Quaternion.fromComplex(re, im);
  }

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  const Quaternion normalize() {
    final double norm = norm();
    if (norm == 0.0) {
      return Quaternion.zero();
    }
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  const Quaternion conjugate() {
    return Quaternion(x, y, -z, w);
  }

  const Quaternion inverse() {
    return Quaternion(x, y, z, w) * conjugate();
  }

  const Quaternion operator +(const other) {
    return Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);
  }

  const Quaternion operator -(const other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  const Quaternion operator *(const other) {
    double a11 = x * x, a12 = x * y, a13 = x * z, a14 = x * w;
    double a21 = y * x, a22 = y * y, a23 = y * z, a24 = y * w;
    double a31 = z * x, a32 = z * y, a33 = z * z, a34 = z * w;
    double a41 = w * x, a42 = w * y, a43 = w * z, a44 = w * w;
    double b11 = other.x * other.x, b12 = other.x * y, b13 = other.x * z, b14 = other.x * w;
    double b21 = other.y * x, b22 = other.y * y, b23 = other.y * z, b24 = other.y * w;
    double b31 = other.z * x, b32 = other.z * y, b33 = other.z * z, b34 = other.z * w;
    double b41 = other.w * x, b42 = other.w * y, b43 = other.w * z, b44 = other.w * w;
    double t00 = a11 * b22 - a21 * b32, t01 = a12 * b33 - a32 * b23, t02 = a13 * b24 - a43 * b34;
    double t10 = a21 * b33 - a31 * b23, t11 = a22 * b34 - a42 * b24, t12 = a31 * b24 - a41 * b34;
    double t20 = a11 * b24 - a41 * b22, t21 = a22 * b34 - a42 * b24, t22 = a33 * b22 - a23 * b33;
    double t30 = a41 * b33 - a31 * b22, t31 = a23 * b34 - a43 * b24, t32 = a12 * b23 - a21 * b32;
    return Quaternion(t00 * a44 + t11 * a43 + t22 * a42 + t33 * a41,
                    t01 * a44 + t12 * a43 + t23 * a42 + t31 * a41,
                    t02 * a44 + t13 * a43 + t21 * a42 + t32 * a41,
                    t30 * a44 + t31 * a43 + t32 * a42 + t03 * a41);
  }

  const Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  @override
  String toString() {
    return '$x + $y*i + $z*j + $w*k';
  }
