class Quaternion {
  double x;
  double y;
  double z;
  double w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion.identity() : this(0.0, 0.0, 0.0, 1.0);

  Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  Quaternion.unit() : this(0.0, 0.0, 0.0, 1.0);

  Quaternion.fromList(List<double> list)
      : x = list[0],
        y = list[1],
        z = list[2],
        w = list[3];

  Quaternion.fromQuaternion(Quaternion q)
      : x = q.x,
        y = q.y,
        z = q.z,
        w = q.w;

  Quaternion.fromAxisAngle(double axisX, double axisY, double axisZ,
      double angle) {
    double sinHalf = sin(angle / 2.0);
    double cosHalf = cos(angle / 2.0);
    return Quaternion(
      axisX * sinHalf,
      axisY * sinHalf,
      axisZ * sinHalf,
      cosHalf,
    );
  }

  Quaternion.fromBasis(Quaternion up, Quaternion right, Quaternion forward) {
    return Quaternion(
      up.x,
      right.y,
      forward.z,
      up.w * right.w * forward.w,
    );
  }

  Quaternion.fromBasisTo(double x, double y, double z) {
    return Quaternion.fromBasis(
      Quaternion.unit(),
      Quaternion(x, 0.0, 0.0, 0.0),
      Quaternion(0.0, y, 0.0, 0.0),
    );
  }

  @override
  bool operator ==(Object other) {
    if (other is Quaternion) {
      return x == other.x &&
          y == other.y &&
          z == other.z &&
          w == other.w;
    }
    return false;
  }

  @override
  int get hashCode => x.hashCode ^ y.hashCode ^ z.hashCode ^ w.hashCode;

  bool get isUnit => w.abs() == 1.0;

  bool get isZero => w.abs() == 0.0;

  bool get isImaginary => w.abs() < 1.0 && w.abs() > 0.0;

  bool get isComplex => w.abs() > 0.0;

  Quaternion conjugate() =>
      Quaternion(x, y, z, -w);

  Quaternion inverse() =>
      Quaternion(x, y, z, w * w) *
      Quaternion.unit() /
      (w * w);

  Quaternion normalized() =>
      Quaternion(x / w, y / w, z / w, 1.0) *
      Quaternion.unit();

  Quaternion operator +(Object other) {
    if (other is Quaternion) {
      return Quaternion(x + other.x, y + other.y, z + other.z, w);
    }
    return other + this;
  }

  Quaternion operator -(Object other) {
    if (other is Quaternion) {
      return Quaternion(x - other.x, y - other.y, z - other.z, w);
    }
    return other - this;
  }

  Quaternion operator -(double scalar) =>
      Quaternion(x - scalar * x, y - scalar * y, z - scalar * z, w);

  Quaternion operator *(double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Object other) {
    if (other is Quaternion) {
      return Quaternion(
        x * other.w + y * other.z - z * other.y + w * other.x,
        y * other.w + z * other.x - x * other.z + w * other.y,
        z * other.w + x * other.y - y * other.x + w * other.z,
        w * other.w,
      );
    }
    if (other is num) {
      return Quaternion(x * other, y * other, z * other, w * other);
    }
    throw ArgumentError('Unsupported operand type');
  }

  double dot(Quaternion other) {
    return x * other.w + y * other.z - z * other.y + w * other.x;
  }

  double norm() {
    return w == 0.0 ? 0.0 : sqrt(x * x + y * y + z * z);
  }

  double angle(Quaternion other) {
    double dot = this.dot(other);
    if (dot < 0.0) dot = -dot;
    double normA = this.norm(), normB = other.norm();
    if (normA == 0.0 || normB == 0.0) return 0.0;
    double angle = acos(dot / (normA * normB));
    return angle * 180.0 / pi;
  }

  double trace() => x * x + y * y + z * z + w * w;

  bool get isReal => w.abs() == 1.0 && !isImaginary;

  bool get isPure => isReal && x == y && x == z;

  bool get isUnitQuaternion => w.abs() == 1.0 && x.abs() == y.abs() && x.abs() == z.abs();

  void rotatePoint(List<double> point, double theta) {
    final q = Quaternion.fromAxisAngle(0.0, 0.0, 0.0, theta);
    for (int i = 0; i < point.length; i++) {
      point[i] = q.x * point[i] + q.y * point[i + 1] + q.z * point[i + 2] + q.w * point[i + 3];
    }
  }

  void applyTo(List<double> result, List<double> data) {
    for (int i = 0; i < data.length; i++) {
      result[i] = x * data[i] + y * data[i + 1] + z * data[i + 2] + w * data[i + 3];
    }
  }

  void toList(List<double> list) {
    list[0] = x;
    list[1] = y;
    list[2] = z;
    list[3] = w;
  }
}

