Map<String, int> fn0(List<int> roundScores, int targetScore) {
  List<int> stack = [];
  for (int score in roundScores) {
    stack.add(score);
  }
  int left = 0;
  int sum = 0;
  int rounds = 0;
  while (left < stack.length) {
    int right = left;
    while (right < stack.length && stack[right] == stack[left]) {
      right++;
    }
    int length = right - left;
    sum += stack.sublist(left, right).fold(0, (a, b) => a + b);
    rounds += length;
    if (sum >= targetScore) {
      break;
    }
    left = right;
  }
  return {
    'totalScore': sum,
    'completedRounds': rounds,
    'remainingDice': stack.length - left,
  };
}

