bool fn0(List<String> phases, int minDuration) {
  if (phases.length < 2) return false;

  Map<String, int> durationCounts = {};
  for (String phase in phases) {
    durationCounts[phase] = (durationCounts[phase] ?? 0) + 1;
  }

  if (durationCounts.length < 2) return false;

  List<int> durations = List.filled(phases.length - 1, 0);
  for (int i = 0; i < phases.length - 1; i++) {
    String from = phases[i];
    String to = phases[i + 1];
    int count = durationCounts[to]! - durationCounts[from]!;
    if (count < 0) return false;
    durations[i] = count;
  }

  int longest = 0;
  for (int d in durations) {
    if (d > longest) longest = d;
  }

  if (longest <= minDuration) return true;
  if (longest == 0) return false;

  for (int start = 0; start < phases.length - 1; start++) {
    int current = durations[start];
    int remaining = longest - current;
    if (remaining <= 0) continue;

    List<int> subDurations = List.filled(remaining, 0);
    for (int i = start + 1; i < phases.length - 1; i++) {
      if (durations[i] > 0) {
        subDurations[i - start - 1] = durations[i];
      }
    }

    bool subValid = fn0(subDurations, minDuration);
    if (subValid) return true;
  }

  return false;
}

