    }
  }

  final prefix = List<int>.filled(n, 0);
  final suffix = List<int>.filled(n, 0);
  prefix[0] = bucketCounts[0];
  for (int i = 1; i < n; i++) prefix[i] = prefix[i - 1] + bucketCounts[i];

  for (int i = n - 1; i >= 0; i--) suffix[i] = suffix[i + 1] + bucketCounts[i];
