  String str = "AABAACAADAABAABA";
  String pattern = "A";

  int m = str.length;
  int n = pattern.length;

  List<List<int>> lps = List.generate(m, (_) => List.filled(n, 0));

  int len = 0;
  int i = 0;

  while (i < n - 1) {
    if (pattern[i] == pattern[i + 1]) {
      len++;
      i++;
    } else {
      len = 0;
      i++;
    }
  }

  for (int lenIndex = 0; lenIndex < len; lenIndex++) {
    lps[0][lenIndex] = len - lenIndex;
  }

  for (int i = 1; i < m; i++) {
    for (int j = 0; j < len; j++) {
      if (pattern[j] == str[i]) {
        lps[i][j] = lps[i - 1][j - 1];
      } else if (len - (j - 1) >= 0 && pattern[j] == str[i - len - 1]) {
        lps[i][j] = len;
      } else {
        lps[i][j] = 0;
      }
    }
  }

  List<int> matches = [];

  for (int i = 0; i < m; i++) {
    for (int j = 0; j < len; j++) {
      if (lps[i][j] == len) {
        matches.add(i);
      }
    }
  }

  print("Text: $str");
  print("Pattern: $pattern");
