  if (n == 0) return 0;
  List<int> dp = List<int>.filled(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    int minVal = samples[i - 1];
    for (int j = i - 1; j >= 0; j--) {
      if (samples[j] < minVal) minVal = samples[j];
