int fn0(List<int> readings, int start, int end) {
  if (end < start) return 0;
  if (end - start + 1 <= 1) {
    List<int> counts = List.filled(16, 0);
    int maxCount = 0;
    for (int r in readings) {
      counts[r % 16]++;
      if (counts[r % 16] > maxCount) maxCount = counts[r % 16];
    }
    return maxCount;
  }
  int mid = start + ((end - start) >> 1);
  List<int> leftCounts = List.filled(16, 0);
  List<int> rightCounts = List.filled(16, 0);
  for (int r in readings) {
    if (r < mid) {
      leftCounts[r % 16]++;
    } else {
      rightCounts[r % 16]++;
    }
  }
  int leftMax = 0;
  int rightMax = 0;
  for (int c in leftCounts) {
    if (c > leftMax) leftMax = c;
  }
  for (int c in rightCounts) {
    if (c > rightMax) rightMax = c;
  }
  int leftCount = 0;
  int rightCount = 0;
  int leftEnd = 0;
  int rightStart = 0;
  if (leftMax >= rightMax) {
    leftCount = leftMax;
    leftEnd = mid;
    rightStart = mid;
    rightCount = rightMax;
  } else {
    rightCount = rightMax;
    rightStart = mid;
    leftCount = leftMax;
    leftEnd = end;
  }
  int overlapCount = 0;
  for (int r in readings) {
    if (r >= leftStart && r <= rightEnd) {
      overlapCount++;
    }
  }
  int splitWays = 1;
  if (leftCount > 0) {
    int maxLeft = 0;
    for (int r in readings) {
      if (r < leftEnd && r >= leftStart) {
        maxLeft++;
      }
    }
    splitWays += fn0(readings, leftStart, leftEnd) * maxLeft;
  }
  if (rightCount > 0) {
    int maxRight = 0;
    for (int r in readings) {
      if (r < rightStart && r >= rightEnd) {
        maxRight++;
      }
    }
    splitWays += fn0(readings, rightStart, rightEnd) * maxRight;
  }
  return overlapCount + splitWays;
}

