    {'name': 'document1', 'description': 'Important company document'},
    {'name': 'document2', 'description': 'Internal project notes'},
    {'name': 'sensitive_data'}, 
    {'name': 'user_management'}, 
    {'name': 'content_moderation'}, 
  ];

  const Map<String, List<int>> permissions = {
    'admin': [1, 2, 3, 4, 5],
    'editor': [1, 2, 3],
    'moderator': [1, 2, 3],
    'viewer': [1],
    'user': [1],
  };

  Map<String, String> rolesHierarchy = {
    'admin': 'root',
    'editor': 'admin',
    'moderator': 'editor',
    'viewer': 'editor',
    'user': 'viewer',
  };

  String? _getRoleName(String user) {
    for (var userRole in users) {
      if (user == userRole['name'] as String) {
        return userRole['role'] as String?;
      }
    }
    return null;
  }

  bool _hasPermission(String role, int permissionMask) {
    if (permissions.containsKey(role)) {
      return (permissions[role]! & permissionMask) != 0;
    }
    return false;
  }

  void _grantPermission(String role, int permissionMask) {
    if (!permissions.containsKey(role)) {
      permissions[role] = 0;
    }
    permissions[role] = (permissions[role]! | permissionMask);
  }

  String _getPermissionsText(String role) {
    if (!permissions.containsKey(role)) return 'N/A';
    var sb = StringBuffer();
    sb.write('Permissions: ');
    _hasPermission(role, 1) ? sb.write('read ') : null;
    _hasPermission(role, 2) ? sb.write('write ') : null;
    _hasPermission(role, 4) ? sb.write('delete ') : null;
    _hasPermission(role, 8) ? sb.write('admin ') : null;
    return sb.toString().padRight(20);
  }

  String _getRoleHierarchy(String role) {
    String? parent = rolesHierarchy[role] as String?;
    if (parent == null) return 'Root';
    var hierarchy = StringBuffer();
    String? current = role;
    do {
      hierarchy.write('$current -> ');
      current = parent;
      parent = rolesHierarchy[current] as String?;
    } while (parent != null);
    hierarchy.write('$current');
    return hierarchy.toString();
  }

  void _displayUserPermissions(String user) {
    var role = _getRoleName(user);
    print('User: $user');
    print('Role: $role');
    print(_getPermissionsText(role));
    print('Role Hierarchy: ${_getRoleHierarchy(role)}');
  }

  void _displayResourceAccess(String resource) {
    var role = _getRoleName('alice'); 
    print('Resource: $resource');
    print('Access GRANTED (Role: $role): ${_hasPermission(role, 4)}');
    print('Access DENIED (Insufficient permissions): ${_hasPermission(role, 1)}');
  }

  print('=== Role-Based Access Control System ===\n');

  print('Total Users: ${users.length}\n');
  print('Total Resources: ${resources.length}\n');
  print('Total Roles: ${roles.length}\n');
  print('Total Permissions: ${permissions.length}\n\n');

