    _displayUserPermissions(user['name'] as String);
  }

  print('\n--- Resource Access Matrix ---\n');
  for (var resource in resources) {
    _displayResourceAccess(resource['name'] as String);
  }

  print('\n--- Access Control Tests ---\n');

  print('Elevating bob to admin role...');
  var bobRole = _getRoleName('bob') as String?;
  if (bobRole != null) {
    _grantPermission(bobRole, 4); 
    print('SUCCESS');
  } else {
    print('  ! User "bob" not found');
  }

  print('Attempting to access admin resource...');
  _displayResourceAccess('sensitive_data');

  print('Current role for "alice": ${_getRoleName('alice')}');

  print('\n--- Permission Elevation Scenario ---\n');
  print('Attempting to access admin resource again...');
  _displayResourceAccess('sensitive_data');

  print('\n--- Permission Inheritance Demo ---\n');
  print('New role for "diana": viewer\n');
  _grantPermission('viewer', 1);
  var viewerRole = _getRoleName('diana') as String?;
  print('Current role for "diana": $viewerRole');
  print('Permissions: ${_getPermissionsText(viewerRole)}');

  print('\n=== System Summary ===\n');
  print('Recent Access Attempts:');
  _displayUserPermissions('alice');
  print('  ' + '-' * 20);
  _displayUserPermissions('bob');
  print('  ' + '-' * 20);
  _displayUserPermissions('charlie');
  print('  ' + '-' * 20);
  _displayUserPermissions('diana');
  print('  ' + '-' * 20);
  _displayUserPermissions('eva');
}

