            if (currentItems[item]!.contains(trans)) {
              freq[item] = freq[item]! + 1.0;
            }
          }
        }
      }
      return;
    }

    for (var item in currentItems.keys) {
      Set<String> itemCopy = currentItems[item]!.toSet();
      itemCopy.remove(item);
      generateFrequentItemsets(itemCopy, freq, transactions);
    }
