List<int> fn0(List<List<int>> grid) {
  int rows = grid.length;
  if (rows == 0) return [];
  int cols = grid[0].length;
  if (cols == 0) return [];
  List<List<int>> dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  List<List<int>> distances = List.generate(rows, (_) => List.filled(cols, -1));
  List<List<int>> queue = [[0, 0]];
  distances[0][0] = 0;
  bool inQueue = true;
  while (inQueue) {
    inQueue = false;
    List<List<int>> nextQueue = [];
    for (List<int> curr in queue) {
      int r = curr[0];
      int c = curr[1];
      for (List<int> d in dirs) {
        int nr = r + d[0];
        int nc = c + d[1];
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
          int dist = distances[r][c] + grid[nr][nc];
          if (distances[nr][nc] == -1 || dist < distances[nr][nc]) {
            distances[nr][nc] = dist;
            if (dist == 0) {
              nextQueue.add([nr, nc]);
              inQueue = true;
            } else {
              queue.add([nr, nc]);
            }
          }
        }
      }
    }
    queue = nextQueue;
  }
  return [distances[r][c] for (int r = 0; r < rows; r++) for (int c = 0; c < cols; c++)];
}

