      : this(1, 0, 2, 1);

  const Rectangle.unitToUnitRight()
      : this(0, 1, 1, 2);

  Rectangle operator +(Point p) =>
      Rectangle(x1 + p.x, y1 + p.y, x2 + p.x, y2 + p.y);

  Rectangle operator -(Point p) =>
      Rectangle(x1 - p.x, y1 - p.y, x2 - p.x, y2 - p.y);

  Rectangle operator *(double scale) =>
      Rectangle(x1 * scale, y1 * scale, x2 * scale, y2 * scale);

  Rectangle operator /(double scale) =>
      Rectangle(x1 / scale, y1 / scale, x2 / scale, y2 / scale);

  Rectangle operator ^(Point p) {
    double dx = p.x, dy = p.y;
    return (dx * dx + dy * dy <= scale * scale)
        ? this & p
        : this;
  }

  Rectangle operator &(Point p) {
    double dx = p.x, dy = p.y;
    return (dx * dx + dy * dy <= scale * scale)
        ? this & p
        : this;
  }

  Rectangle operator |(Point p) {
    double dx = p.x, dy = p.y;
    return (dx * dx + dy * dy <= scale * scale)
        ? this | p
        : this;
  }

  Rectangle operator &(Rectangle r) {
    if (x1 <= r.x1 && x2 >= r.x2 && y1 <= r.y1 && y2 >= r.y2) {
      return this & r;
    }
    return this;
  }

  Rectangle operator |(Rectangle r) {
    if (x1 <= r.x1 && x2 >= r.x2 && y1 <= r.y1 && y2 >= r.y2) {
      return this | r;
    }
    return this;
  }

  Rectangle operator ^(Rectangle r) {
    if ((x1 <= r.x1 && r.x2 <= x2) ||
        (x1 <= r.x2 && r.x1 <= x2) ||
        (y1 <= r.y1 && r.y2 <= y2) ||
        (y1 <= r.y2 && r.y1 <= y2)) {
      return this ^ r;
    }
    return this;
  }

  const Rectangle.unitCircle()
      : this(0, 0, 1, 1);

  const Rectangle.unitSquare()
      : this(0, 0, 1, 1);

  const Rectangle.originToUnit()
      : this(0, 0, 1, 1);

