  double get perimeter => 2 * (x1 + y1) + 2 * (x2 + y2);

  double get scale => (x2 - x1 + 1) * (y2 - y1 + 1);

  Rectangle get translated(Point p) {
    double dx = p.x, dy = p.y;
    return Rectangle(x1 + dx, y1 + dy, x2 + dx, y2 + dy);
  }

