  String toString() => 'Rectangle(center: ($x, $y), halfWidth: $width, halfHeight: $height)';

  Rectangle.square(double side) : this(side, side);

  Rectangle.fromPoints(Point p1, Point p2)
      : width = (p1.x - p2.x).abs(),
        height = (p1.y - p2.y).abs(),
        x = p1.x,
        y = p1.y;

  bool contains(Point p) =>
      x < p.x + width && p.x < x + width &&
      y < p.y + height && p.y < y + height;

  bool overlaps(Rectangle r) =>
      contains(r.p1) || contains(r.p2) ||
      r.contains(this);

  Point get p1 => x < x + width ? Point(x, y) : Point(x + width, y);
  Point get p2 => x < x + width ? Point(x + width, y) : Point(x, y);
}

