  const double EarthRadius = 6.37814e7; 

  const double G = 6.67300e-11; 

  print('On Earth, the gravitational constant G is approximately ${G.toStringAsFixed(9)} kg');
  print('The Earth has a mass of ${EarthMass.toStringAsFixed(9)} kg');
  print('The radius of the Earth is ${EarthRadius.toStringAsFixed(9)} m');

  double mass = 70.0;
  double distance = EarthRadius + 10.0; 
  double force = calculateGravitationalForce(mass, EarthMass, distance);
  print('On ${distance.toStringAsFixed(9)} m above the Earth, '
        'you would weigh ${mass.toStringAsFixed(2)} kg');
}

double calculateGravitationalForce(double massA, double massB, double distance) {
  double G = 6.67300e-11; 
  double force = G * massA * massB / (distance * distance);
  return force;
}

