  List<List<int>> clusters = List.generate(k, (_) => []);

  List<List<double>> centroids = List.generate(k, (_) => [0.0, 0.0]);

  bool converged = false;

  for (int iter = 0; iter < maxIter && !converged; iter++) {

    List<int> pointsInCluster = [];

    for (int i = 0; i < points.length; i++) {

      double minDist = double.infinity;
      int clusterId = 0;

      for (int j = 0; j < k; j++) {

        double dist = 0.0;
        for (int d = 0; d < points[i].length; d++) {
          dist += pow(points[i][d] - centroids[j][d], 2);
        }

        if (dist < minDist) {
          minDist = dist;
          clusterId = j;
        }
      }

      if (clusterId == 0) {

        pointsInCluster.add(i);
        labels[i] = 0;
      } else {

        clusters[clusterId].add(i);
        labels[i] = clusterId;
      }
    }

    for (int c = 0; c < k; c++) {

      if (pointsInCluster.isNotEmpty) {

        centroids[c] = [
          (pointsInCluster[0] + pointsInCluster[1]) / 2.0,
          (pointsInCluster[0] + pointsInCluster[1]) / 2.0,
        ];
