    for (int c = 0; c < k; c++) {
      if (clusters[c].length != pointsInCluster.length) {
        converged = false;
        break;
      }
      for (int i = 0; i < pointsInCluster.length; i++) {
        if (clusters[c][i] != pointsInCluster[i]) {
          converged = false;
          break;
        }
      }
