void fn0() {

  List<List<double>> points = [
    [1.0, 2.0],
    [1.5, 2.5],
    [3.0, 3.5],
    [4.0, 4.5],
    [2.0, 1.5],
    [7.0, 1.0],
  ];

  final random = Random(0);

  int k = 3; 
  List<List<int>> clusters = List.generate(k, (_) => <int>[]);

  List<int> pointIndices = List.generate(points.length, (i) => i);

  int epoch = 0;
  double dist = double.infinity;

  while (epoch < 1000) {
    epoch++;

    int clusterIndex = random.nextInt(k);
    List<int> currentCluster = clusters[clusterIndex];

    for (int i = 0; i < points.length; i++) {
      if (currentCluster.contains(i)) {
        continue;
      }

      double minDist = double.infinity;
      int bestCluster = clusterIndex;

      for (int c = 0; c < k; c++) {
        if (c == clusterIndex) continue;
        List<int> cPoints = clusters[c];
        for (int p = 0; p < points.length; p++) {
          if (cPoints.contains(p)) continue;
          double dist = (points[i][0] - points[p][0]).abs() + (points[i][1] - points[p][1]).abs();
          if (dist < minDist) {
            minDist = dist;
            bestCluster = c;
          }
        }
      }

      if (minDist == double.infinity) {
        currentCluster.add(i);
      } else {
        clusters[bestCluster].add(i);
      }
    }

    double newDist = 0.0;
    for (int c = 0; c < k; c++) {
      List<int> clusterPoints = clusters[c];
      if (clusterPoints.length < 2) continue;

      double cx = 0.0;
      double cy = 0.0;
      for (int p = 0; p < clusterPoints.length; p++) {
        cx += points[clusterPoints[p]][0];
        cy += points[clusterPoints[p]][1];
      }

      newDist += (cx / clusterPoints.length) * (cy / clusterPoints.length);
    }

    if (newDist <= dist) {
      dist = newDist;
      clusters = List.from(clusters);
    }
  }

  print('Cluster ${clusters[0]} centroid: (${clusters[0][0]}, ${clusters[0][1]})');
  print('Cluster ${clusters[1]} centroid: (${clusters[1][0]}, ${clusters[1][1]})');
  print('Cluster ${clusters[2]} centroid: (${clusters[2][0]}, ${clusters[2][1]})');

  print('  Points: ${clusters[0]}, ${clusters[1]}, ${clusters[2]}');
  print('Converged in $epoch iteration(s).');
}

