    [4.5, 5.0],
  ];

  int k = 3; 

  Random rand = Random(0);
  List<int> clusters = List.filled(points.length, -1);

  for (int i = 0; i < points.length; i++) {
    clusters[i] = rand.nextInt(k);
  }

  double eps = 0.01;
  int maxIter = 100;

  for (int iter = 0; iter < maxIter; iter++) {

    List<List<double>> clustersNew = List.generate(k, (_) => []);

    for (int i = 0; i < points.length; i++) {
      int label = clusters[i];
      if (label == -1) {
        for (int c = 0; c < k; c++) {
          if (label == c) {
            label = c;
            break;
          }
        }
      }
      clustersNew[label].add(points[i]);
    }

    List<List<double>> centroidsNew = List.generate(k, (_) => []);

    for (int c = 0; c < k; c++) {
      if (clustersNew[c].isEmpty) {
        centroidsNew[c] = List.from(points[rand.nextInt(points.length)]);
      } else {
        double x = 0.0, y = 0.0;
        for (var p in clustersNew[c]) {
          x += p[0];
          y += p[1];
        }
        centroidsNew[c] = [x / clustersNew[c].length, y / clustersNew[c].length];
      }
    }

    bool changed = false;
    for (int i = 0; i < points.length; i++) {
      double dist = double.infinity;
      for (int c = 0; c < k; c++) {
        double d = (points[i][0] - centroidsNew[c][0]).abs() +
            (points[i][1] - centroidsNew[c][1]).abs();
        if (d < dist) {
          dist = d;
          clusters[i] = c;
        }
      }
      if (dist > eps) {
        changed = true;
      }
    }

    if (!changed) {
      break;
    }

    clusters = centroidsNew;
    centroids = clustersNew;

    print('Converged in $iter iteration(s).');
  }

  print('Cluster ${clusters[0]}: ${clusters[0]}');
  print('Cluster ${clusters[1]}: ${clusters[1]}');
  print('Cluster ${clusters[2]}: ${clusters[2]}');
