@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {



  final random = Random(0);

  final data = <List<double>>[
    [1.0, 2.0],
    [2.0, 2.5],
    [2.0, 3.0],
    [3.0, 3.5],
    [4.0, 4.0],
    [4.5, 4.5],
    [7.0, 7.0],
  ];

  final int k = 3; 

  final int maxIterations = 50;

  double centroid(List<double> point) =>
      point.fold(0.0, (double current, double d) => current + d) / point.length;

  Set<int> pointsInCluster(List<double> point, List<List<double>> clusters) {
    final int idx = clusters.length;
    for (final cluster in clusters) {
      if (cluster.length == point.length) {
        return {idx};
      }
    }
    final clustersNew = List.generate(idx + 1, (_) <List<double>>[]);
    int idxNew = 0;
    for (final cluster in clusters) {
      clustersNew[idxNew] = List<double>.from(cluster);
      idxNew++;
    }
    clustersNew[idxNew] = List<double>.from(point);
    final result = <int>{};
    for (final cluster in clustersNew) {
      if (cluster.length == point.length) {
        result.add(idxNew);
      }
    }
    return result;
  }

  final clusters = <List<double>>[];
  var point = data[0];
  clusters.add([point.fold(0.0, (double current, double d) => current + d) / point.length]);
  final pointIdx = clusters.length - 1;
  for (int i = 1; i < data.length; i++) {
    final newPoint = data[i];
    final newIdx = clusters.length;
    clusters.add([]);
    var minDist = double.infinity;
    for (int j = 0; j < pointIdx; j++) {
      final dist = centroid(point).abs() + centroid(data[j]).abs();
      if (dist < minDist) {
        minDist = dist;
        final nearest = j;
      }
    }
    clusters[newIdx] = List<double>.from(data[nearest]);
    final neighbors = pointsInCluster(newPoint, clusters);
    for (final idx in neighbors) {
      if (idx < newIdx) {
        clusters[idx] = List<double>.from(newPoint);
      }
    }
    point = newPoint;
    pointIdx = newIdx;
  }

  int iterations = 0;
  var converged = false;
  while (!converged && iterations < maxIterations) {
    final newClusters = <List<double>>[];
    for (final cluster in clusters) {
      if (cluster.length > 1) {
        var newPoint = cluster[0];
        newClusters.add([]);
        for (int j = 1; j < cluster.length; j++) {
          newPoint = newPoint + cluster[j];
        }
        newClusters[newClusters.length - 1] = [newPoint / cluster.length];
        for (final existing in clusters) {
          if (existing.length == newPoint.length) {
            existing[0] = existing[0] + newPoint;
          }
        }
      } else {
        newClusters.add(List<double>.from(cluster));
      }
    }
    clusters = newClusters;
    if (clusters.length == 1) {
      converged = true;
    } else {
      for (final cluster in clusters) {
        if (cluster.length > 1) {
          final old = centroid(cluster[0]);
          final newCentroid = centroid(cluster.reduce((double a, double b) => a + b));
          if (old != newCentroid) {
            converged = false;
          }
        }
      }
    }
    iterations++;
  }

  if (converged) {
    print('Converged in $iterations iteration(s).');
    print('Cluster ${clusters.length} centroids:');
    for (final cluster in clusters) {
      print('  Points: ${cluster.map((p) => p.toString()).join(', ')}');
    }
  } else {
    print('K-Means failed to converge.');
  }
}

