    if (isDominant) {
      result.add('$index: $p');
      return;
    }

    List<int> filtered = p.map((x) => x).toList();
    filtered.sort((a, b) {
      String keyA = '${a == 0 ? 'G' : (a == 1 ? 'B' : 'R')}:$a';
      String keyB = '${b == 0 ? 'G' : (b == 1 ? 'B' : 'R')}:$b';
      int cmp = keyA.compareTo(keyB);
      if (cmp != 0) return cmp;
      if (a != b) {
        return a.compareTo(b);
      }
      return 0;
    });

    int total = filtered.reduce((a, b) => a + b);
    if (total < 30) {
      result.add('$index: $filtered');
      return;
    }

    List<List<int>> clusters = [];
    int i = 0;
    while (i < filtered.length) {
      int j = i;
