      List<int> prev = merged[k - 1];
      List<int> curr = clusters[k];
      if (prev[0] < curr[0] && prev[1] < curr[1] && prev[2] < curr[2]) {
        prev[0] += curr[0];
        prev[1] += curr[1];
        prev[2] += curr[2];
      } else {
        merged.add(curr);
      }
    }

    for (List<int> p in merged) {
      if (isDominant(p)) {
        result.add('$index: $p');
        return;
      }
    }
    if (merged.isNotEmpty) {
      result.addAll(merged.map((p) => '$index: $p'));
    } else {
