  }

  Set<int> xs = {};
  Set<int> ys = {};
  for (var zone in zones) {
    xs.add(zone[0]);
    xs.add(zone[2]);
    ys.add(zone[1]);
    ys.add(zone[3]);
  }

  List<int> xList = xs.toList()..sort();
  List<int> yList = ys.toList()..sort();

  List<int> result = <int>[];

  for (int i = 0; i < xList.length - 1; i++) {
    for (int j = 0; j < yList.length - 1; j++) {
      bool touch = false;
      for (var zone in zones) {
        if (zone[0] <= xList[i] && xList[i + 1] <= zone[2] && zone[1] <= yList[j] && yList[j + 1] <= zone[3]) {
          touch = true;
          break;
        }
      }
      if (!touch) continue;

      List<List<int>> valid = <List<int>>[];
      for (var zone in zones) {
        if (zone[0] <= xList[i] && xList[i + 1] <= zone[2] && zone[1] <= yList[j] && yList[j + 1] <= zone[3]) {
          valid.add(<int>[zone[0], zone[1], zone[2], zone[3]]);
