        }
        if (a[0] != b[0]) {
          return a[0].compareTo(b[0]);
        }
        return a[1].compareTo(b[1]);
      });

      int minDist = valid[0][0];
      int maxDist = valid[0][2];

      for (int k = 1; k < valid.length; k++) {
        if (valid[k][0] < minDist) {
          minDist = valid[k][0];
        }
        if (valid[k][2] > maxDist) {
          maxDist = valid[k][2];
        }
      }

      if ((minDist - query[0]).abs() + (query[1] - maxDist).abs() <= radius) {
        result.add(minDist);
      }
    }
  }

  return result;
}

