  for (int r = 0; r < rows.length; r++) {
    for (int c = 0; c < cols; c++) {
      if (rows[r][c] == '#') {
        int area = 1;
        bool valid = true;
        for (int nr = r; nr < rows.length; nr++) {
          if (rows[nr][c] == '#') {
            area *= (nr - r + 1);
