          rects.add([r, c, r, c]);
        } else {
          rects.add([r, c, r + area - 1, c + area - 1]);
        }
      }
    }
  }
  List<List<int>> results = [];
  for (var rect in rects) {
    if (rects.isEmpty) {
      results.add([rect[0], rect[1], rect[2], rect[3]]);
      continue;
    }
    int overlap = 0;
    for (var other in rects) {
      if (other == rect) continue;
      int dx = (rect[2] < other[2] ? rect[2] : other[2]) - (rect[0] > other[0] ? rect[0] : other[0]);
      int dy = (rect[3] < other[3] ? rect[3] : other[3]) - (rect[1] > other[1] ? rect[1] : other[1]);
