int fn0(List<int> floorRequests, int currentFloor) {
  int left = 0;
  int right = floorRequests.length - 1;
  int result = -1;
  while (left <= right) {
    int mid = left + (right - left) ~/ 2;
    if (floorRequests[mid] == currentFloor) {
      result = mid;
      break;
    }
