  int cols = requests[0].length;
  int minX = requests[0][0], maxX = requests[0][cols - 1];
  int minY = requests[0][0], maxY = requests[0][cols - 1];
  for (final req in requests) {
    int x = req[0], y = req[1], w = req[2], h = req[3];
    if (x < minX) minX = x;
    if (x > maxX) maxX = x;
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  int totalArea = (maxX - minX + 1) * (maxY - minY + 1);
  int shadedArea = 0;
  for (final req in requests) {
    int x = req[0], y = req[1], w = req[2], h = req[3];
    if (w <= 0 || h <= 0) continue;
    int overlapLeft = minX > x + w ? minX : x + w;
    int overlapBottom = minY > y + h ? minY : y + h;
    int overlapRight = maxX < x + w + 1 ? maxX : x + w + 1;
    int overlapTop = maxY < y + h + 1 ? maxY : y + h + 1;
    if (overlapLeft <= overlapRight && overlapBottom <= overlapTop) {
      int overlapArea = (overlapRight - overlapLeft + 1) * (overlapTop - overlapBottom + 1);
      shadedArea += overlapArea;
    }
  }
  return shadedArea;
}

